  "check_code": "import hashlib
import re
import sqlite3
from pathlib import Path

RUN_ID = "AUTH-IDEM-8FA4A7ADF39A"
CHANGE_TICKET = "CHG-20250618-HTTPS-017"
RECORD_IDS = {"DOMAIN_ZWFW_MAIN", "DOMAIN_ZWFW_WWW", "DOMAIN_ZWFW_API"}
DOMAIN_NAMES = {"zwfw.haizhou-yungang.cn", "www.zwfw.haizhou-yungang.cn", "api.zwfw.haizhou-yungang.cn"}
EXEMPT_ID = "DNSR-OPS-ALIAS-0047"


def _connect(ws, db_name="state.db"):
    db = Path(ws).resolve().parent / "system" / "infoblox_ddi" / db_name
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    return con


def check_answer_analysis_and_scope(ws):
    p = Path(ws) / "answer.md"
    text = p.read_text(encoding="utf-8", errors="ignore") if p.exists() else ""
    low = text.lower()
    missing = [d for d in DOMAIN_NAMES if d not in low]
    if missing:
        return {"score": 0, "detail": f"答案缺少请求域名: {missing}"}
    business_ok = (
        "门户主站" in text
        and "www" in low and "兼容入口" in text
        and "api" in low and "政务" in text
    )
    ip_count = len(re.findall(r"198\.51\.100\.42", text))
    alias_ok = (
        "ops-admin.zwfw.haizhou-yungang.cn" in low
        and ("内网" in text or "internal" in low)
        and ("acmeexempt" in low or "acme_exempt" in low or "豁免" in text)
    )
    if not business_ok or ip_count < 3 or not alias_ok:
        return {"score": 0, "detail": "答案未完整给出业务含义、三条有效 A 记录或排除别名豁免依据"}
    return {"score": 1, "detail": "答案完整覆盖三域名业务含义、Production A 记录及排除别名"}


def check_audit_run_and_probes(ws):
    with _connect(ws) as con, _connect(ws, "state.db.pinned_backup") as baseline:
        run = con.execute("SELECT * FROM authorization_runs WHERE run_id=?", (RUN_ID,)).fetchone()
        probes = con.execute(
            """SELECT p.*, r.normalized_fqdn, r.record_id AS dns_record_id
               FROM port80_probes p JOIN dns_records r ON r.record_id=p.record_id
               WHERE p.run_id=? ORDER BY r.normalized_fqdn""", (RUN_ID,)
        ).fetchall()
        duplicate_runs = con.execute(
            "SELECT COUNT(*) FROM authorization_runs WHERE run_id=?", (RUN_ID,)
        ).fetchone()[0]
        baseline_request_ids = {r[0] for r in baseline.execute(
            "SELECT certificate_request_id FROM authorization_runs"
        ).fetchall()}
        request_id = (run["certificate_request_id"] or "").strip() if run else ""
        request_unique = con.execute(
            "SELECT COUNT(*) FROM authorization_runs WHERE certificate_request_id=?", (request_id,)
        ).fetchone()[0] == 1
    if run is None:
        return {"score": 0, "detail": "未找到固定幂等键对应的父运行"}
    request_ok = bool(request_id) and request_id != CHANGE_TICKET and request_id not in baseline_request_ids
    expected = {
        "run_mode": "PRODUCTION",
        "overall_result": "RUNNING",
        "change_ticket": CHANGE_TICKET,
        "finished_at": None,
    }
    mismatch = {k: (run[k], v) for k, v in expected.items() if run[k] != v}
    if not request_ok or not request_unique:
        mismatch["certificate_request_id"] = (run["certificate_request_id"], "new unique non-empty audit request id")
    if not (run["initiated_by"] or "").strip():
        mismatch["initiated_by"] = (run["initiated_by"], "non-empty initiating identity")
    got_ids = {r["dns_record_id"] for r in probes}
    got_names = {r["normalized_fqdn"] for r in probes}
    if mismatch:
        return {"score": 0, "detail": f"父运行字段不符: {mismatch}"}
    if duplicate_runs != 1:
        return {"score": 0, "detail": f"固定幂等键对应 {duplicate_runs} 个父运行，未满足幂等性"}
    if len(probes) != 3 or got_ids != RECORD_IDS or got_names != DOMAIN_NAMES:
        return {"score": 0, "detail": f"探测集合不符: count={len(probes)}, ids={sorted(got_ids)}, names={sorted(got_names)}"}
    bad = [(r["probe_id"], r["error_code"], r["reachable"], r["http_status"]) for r in probes
           if r["error_code"] != "PROBE_QUEUED" or r["reachable"] != 0 or r["http_status"] is not None]
    if bad:
        return {"score": 0, "detail": f"探测未保持排队初态: {bad}"}
    return {"score": 1, "detail": "父运行与三个公网 SAN 探测后态正确且请求/变更组合唯一"}


def check_no_exempt_alias_probe(ws):
    with _connect(ws) as con:
        row = con.execute(
            """SELECT COUNT(*) FROM port80_probes p
               JOIN dns_records r ON r.record_id=p.record_id
               WHERE p.run_id=? AND (r.record_id=? OR r.normalized_fqdn=?)""",
            (RUN_ID, EXEMPT_ID, "ops-admin.zwfw.haizhou-yungang.cn"),
        ).fetchone()
    if row[0] != 0:
        return {"score": 0, "detail": "内网豁免别名被错误排队"}
    return {"score": 1, "detail": "ops-admin 豁免别名未建立探测"}


def _row_digest(con, table, ids):
    cols = [r[1] for r in con.execute(f"PRAGMA table_info({table})").fetchall()]
    order = ",".join(cols)
    key_col = cols[0]
    placeholders = ",".join("?" for _ in ids)
    rows = con.execute(
        f"SELECT {order} FROM {table} WHERE {key_col} IN ({placeholders}) ORDER BY {key_col}",
        tuple(ids),
    ).fetchall()
    kept = [tuple(r) for r in rows]
    return hashlib.sha256(repr(kept).encode()).hexdigest()


def check_unrelated_rows_unchanged(ws):
    with _connect(ws) as current, _connect(ws, "state.db.pinned_backup") as baseline:
        for table in ("dns_zones", "dns_records", "authorization_runs", "port80_probes", "acme_challenges"):
            key_col = baseline.execute(f"PRAGMA table_info({table})").fetchall()[0][1]
            ids = [r[0] for r in baseline.execute(f"SELECT {key_col} FROM {table}").fetchall()]
            if _row_digest(current, table, ids) != _row_digest(baseline, table, ids):
                return {"score": 0, "detail": f"既有 {table} 记录发生非预期变化"}
    return {"score": 1, "detail": "非目标历史记录保持不变"}",
